const SYMBOLS={"US30": "^DJI", "US500": "^GSPC", "NAS100": "^NDX", "GER40": "^GDAXI", "UK100": "^FTSE", "JP225": "^N225", "HK50": "^HSI", "WTIUSD": "CL=F", "BRENTUSD": "BZ=F", "NATGAS": "NG=F"};
const marketHandler={async fetch(request,env){const url=new URL(request.url);if(url.pathname!='/api/market')return env.ASSETS.fetch(request);if(request.method!=='GET')return Response.json({error:'Method not allowed'},{status:405});let symbol=url.searchParams.get('symbol'),upstream=SYMBOLS[symbol];if(!upstream)return Response.json({error:'Unsupported symbol'},{status:400});try{let response=await fetch('https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(upstream)+'?interval=1d&range=5d',{headers:{'User-Agent':'Mozilla/5.0'},signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Provider HTTP '+response.status);let body=await response.json(),meta=body.chart?.result?.[0]?.meta;if(!(Number.isFinite(meta?.regularMarketPrice)&&meta.regularMarketPrice>0&&meta.regularMarketTime>0))throw Error('Provider has no valid quote');return Response.json({symbol,reference:upstream,price:meta.regularMarketPrice,currency:meta.currency,asOf:new Date(meta.regularMarketTime*1000).toISOString(),source:'Yahoo Finance',kind:['WTIUSD','BRENTUSD','NATGAS'].includes(symbol)?'futures':'index'},{headers:{'Cache-Control':'public, max-age=60'}})}catch(e){return Response.json({error:'Sumber harga belum tersedia. Coba lagi.'},{status:502,headers:{'Cache-Control':'no-store'}})}}};
const ASSETS={"/index.html": {"type": "text/html; charset=utf-8", "base64": ""}, "/manifest.webmanifest": {"type": "application/manifest+json", "base64": ""}, "/sw.js": {"type": "text/javascript", "base64": ""}, "/icon-192.png": {"type": "image/png", "base64": ""}, "/icon-512.png": {"type": "image/png", "base64": ""}};
export default {async fetch(request,env,ctx){let path=new URL(request.url).pathname;if(path==="/api/market")return marketHandler.fetch(request,env);if(path==="/")path="/index.html";let asset=ASSETS[path];if(!asset)return new Response("Not found",{status:404});if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405});let bytes=Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0));return new Response(request.method==="HEAD"?null:bytes,{headers:{"Content-Type":asset.type,"Cache-Control":path==="/sw.js"?"no-cache":"public, max-age=0, must-revalidate","X-Content-Type-Options":"nosniff"}})}};
